From b51dd43f4c302a204dbbc2b378cc0a8b7958604b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:34:49 +0100
Subject: [PATCH] applet, kded: don't show a connection as working before it's
 checked

Right after a connection activated, the icon and the notification showed
it as working while NetworkManager was still checking whether it reaches
the Internet. Show it as busy and delay the notification until then.

BUG: 513222
---
 kded/notification.cpp   | 62 ++++++++++++++++++++++++++++++++++++++---
 kded/notification.h     |  7 +++++
 libs/connectionicon.cpp |  8 ++++++
 libs/editor/uiutils.cpp | 11 ++++++++
 libs/editor/uiutils.h   |  6 ++++
 5 files changed, 90 insertions(+), 4 deletions(-)

diff --git a/kded/notification.cpp b/kded/notification.cpp
index 217998364..751ad7ec7 100644
--- a/kded/notification.cpp
+++ b/kded/notification.cpp
@@ -24,6 +24,7 @@

 #include <algorithm>
 #include <chrono>
+#include <utility>

 using namespace std::chrono_literals;

@@ -47,6 +48,13 @@ Notification::Notification(QObject *parent)
             this,
             QOverload<const QString &>::of(&Notification::addActiveConnection));

+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::connectivityChanged, this, &Notification::onConnectivityChanged);
+
+    m_connectivityCheckTimer = new QTimer(this);
+    m_connectivityCheckTimer->setSingleShot(true);
+    m_connectivityCheckTimer->setInterval(30s);
+    connect(m_connectivityCheckTimer, &QTimer::timeout, this, &Notification::showPendingActivatedNotifications);
+
     QDBusConnection::systemBus().connect(QStringLiteral("org.freedesktop.login1"),
                                          QStringLiteral("/org/freedesktop/login1"),
                                          QStringLiteral("org.freedesktop.login1.Manager"),
@@ -321,10 +329,6 @@ void Notification::onActiveConnectionStateChanged(NetworkManager::ActiveConnecti
 {
     auto ac = qobject_cast<NetworkManager::ActiveConnection *>(sender());

-    QString eventId, text, iconName;
-    const QString acName = ac->id();
-    const QString connectionId = ac->id();
-
     if (state == NetworkManager::ActiveConnection::Activated) {
         // Don't send notifications about activated connections just because the
         // daemon was launched as these were not explicitly user-initiated actions,
@@ -345,6 +349,56 @@ void Notification::onActiveConnectionStateChanged(NetworkManager::ActiveConnecti
             return;
         }

+        if (UiUtils::isConnectivityBeingChecked()) {
+            qCDebug(PLASMA_NM_KDED_LOG) << "Delaying connection activated notification until the connectivity check is done";
+            if (!m_pendingActivatedConnections.contains(ac->path())) {
+                m_pendingActivatedConnections << ac->path();
+            }
+            m_connectivityCheckTimer->start();
+            return;
+        }
+    } else {
+        m_pendingActivatedConnections.removeAll(ac->path());
+    }
+
+    notifyActiveConnectionState(ac, state);
+}
+
+void Notification::onConnectivityChanged(NetworkManager::Connectivity connectivity)
+{
+    if (UiUtils::isConnectivityBeingChecked()) {
+        return;
+    }
+
+    m_connectivityCheckTimer->stop();
+
+    // With limited connectivity or a captive portal, the connectivity monitor tells the user instead
+    if (connectivity != NetworkManager::Full) {
+        m_pendingActivatedConnections.clear();
+        return;
+    }
+
+    showPendingActivatedNotifications();
+}
+
+void Notification::showPendingActivatedNotifications()
+{
+    const QStringList pendingConnections = std::exchange(m_pendingActivatedConnections, {});
+    for (const QString &path : pendingConnections) {
+        const NetworkManager::ActiveConnection::Ptr ac = NetworkManager::findActiveConnection(path);
+        if (ac && ac->state() == NetworkManager::ActiveConnection::Activated) {
+            notifyActiveConnectionState(ac.data(), NetworkManager::ActiveConnection::Activated);
+        }
+    }
+}
+
+void Notification::notifyActiveConnectionState(NetworkManager::ActiveConnection *ac, NetworkManager::ActiveConnection::State state)
+{
+    QString eventId, text, iconName;
+    const QString acName = ac->id();
+    const QString connectionId = ac->id();
+
+    if (state == NetworkManager::ActiveConnection::Activated) {
         eventId = QStringLiteral("ConnectionActivated");
         text = i18n("Connection '%1' activated.", acName);

