diff --git a/libs/editor/uiutils.cpp b/libs/editor/uiutils.cpp
index ba42f2d8b..103af90a1 100644
--- a/libs/editor/uiutils.cpp
+++ b/libs/editor/uiutils.cpp
@@ -684,6 +684,17 @@ bool UiUtils::isLiveImage()
     return false;
 }

+bool UiUtils::isConnectivityBeingChecked()
+{
+    if (!NetworkManager::isConnectivityCheckEnabled() || !NetworkManager::isConnectivityCheckAvailable()) {
+        return false;
+    }
+
+    // NetworkManager keeps the previous result until the first check after activation finishes
+    const NetworkManager::Connectivity connectivity = NetworkManager::connectivity();
+    return connectivity == NetworkManager::UnknownConnectivity || connectivity == NetworkManager::NoConnectivity;
+}
